'use strict';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7z M8 12l3 3 5-6',check:'m5 12 4 4L19 6',clipboard:'M9 5H5v16h14V5h-4 M9 3h6v4H9z M8 12h8 M8 16h5',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',stop:'M7 3h10l4 4v10l-4 4H7l-4-4V7z M9 9l6 6 M15 9l-6 6',arrow:'M4 12h16 M14 6l6 6-6 6',plus:'M12 5v14 M5 12h14',close:'m6 6 12 12 M18 6 6 18',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',network:'M9 3h6v6H9z M3 16h6v6H3z M15 16h6v6h-6z M12 9v4 M6 16v-3h12v3',server:'M4 3h16v7H4z M4 14h16v7H4z M7 6.5h.01 M7 17.5h.01 M11 6.5h6 M11 17.5h6',wifi:'M3 9a15 15 0 0 1 18 0 M6 13a10 10 0 0 1 12 0 M9 17a5 5 0 0 1 6 0 M12 21h.01',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',refresh:'M20 7v5h-5 M4 17v-5h5 M5 7a8 8 0 0 1 13-2l2 2 M19 17A8 8 0 0 1 6 19l-2-2',key:'M14 8a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M12 12l9 9 M16 16l3-3 M18 18l3-3',play:'m8 4 12 8-12 8z',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',lock:'M5 10h14v12H5z M8 10V6a4 4 0 0 1 8 0v4 M12 15v3'};
const icon=name=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.info}"/></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(text,tone='')=>`<span class="badge ${tone}">${text}</span>`;
const btn=(text,action,extra='',kind='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${text}</button>`;
const $=selector=>document.querySelector(selector);
const queryGroups=[['system','系统信息','负载、内存、运行时间和固件版本','server'],['network','网络状态与流量','WAN / LAN、DNS、网口速率和流量计数','network'],['devices','设备与 DHCP','设备名称、租约和无线关联客户端','users'],['logs','系统日志','读取系统及网络日志，隐藏敏感字段','file']];
const operationGroups=[['node','切换 OpenClash 节点','仅限现有代理组内的节点，不修改订阅','network'],['mode','切换代理模式','规则 / 全局 / 直连，可恢复原模式','shield'],['restart','重启 OpenClash','可能短暂中断代理连接，须逐笔审批','refresh']];
let state,view='overview',selectedClient='codex',selectedRequest='REQ-0241',filterClient='all',filterResult='all',search='',offset=0,toastTimer,dialogReturnFocus;
const now=()=>Date.now()+offset;
function freshState(){const time=Date.now();return{paused:false,clients:[{id:'codex',name:'Codex',description:'桌面开发助手',active:true,queries:['system','network','devices','logs'],operations:{},limit:60},{id:'openclaw',name:'OpenClaw',description:'日常网络助手',active:true,queries:['network','devices'],operations:{},limit:30}],requests:[makeRequest('REQ-0241','codex','node',time),makeRequest('REQ-0242','openclaw','lan',time)],audit:[{time:time-3*60000,client:'codex',text:'读取 WAN / LAN 状态',result:'查询通过',tone:'green',type:'query'},{time:time-12*60000,client:'admin',text:'为 Codex 开启系统、网络、设备和日志查询',result:'授权已更新',tone:'blue',type:'grant'},{time:time-28*60000,client:'openclaw',text:'申请修改管理地址，等待管理员逐笔审批',result:'等待审批',tone:'amber',type:'request'}]};}
function makeRequest(id,client,kind,time=now()){const sensitive=kind==='lan',restart=kind==='restart';return{id,client,kind,sensitive,requiresReview:sensitive||restart,title:sensitive?'修改 LAN 管理地址':restart?'重启 OpenClash 服务':'切换 OpenClash 代理节点',before:sensitive?'192.168.1.1':restart?'运行中':'自动选择',after:sensitive?'192.168.2.20':restart?'重启并重新加载':'香港 · 低延迟 01',field:sensitive?'network.lan.ipaddr':restart?'openclash.service':'OpenClash / PROXY',reason:sensitive?'调整管理地址，以配合新的局域网地址规划。':'当前代理访问不稳定，希望切换至已有节点以排查问题。',created:time,expires:time+300000,status:'pending',reconnected:false};}
function client(id){return state.clients.find(c=>c.id===id);}
function clientName(id){return id==='admin'?'管理员':client(id)?.name||id;}
function avatar(c){return `<span class="client-avatar ${c.id==='openclaw'?'teal':''}">${esc(c.name.slice(0,1))}</span>`;}
function clock(ms){const s=Math.max(0,Math.ceil(ms/1000));return`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function timeLabel(time){return new Date(time).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});}
function addAudit(id,text,result='已完成',tone='green',type='operation'){state.audit.unshift({time:now(),client:id,text,result,tone,type});}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
function remaining(req){return `<span class="remaining" data-expires="${req.expires}">${clock(req.expires-now())} 后失效</span>`;}
function requestBadge(r){return badge(r.sensitive?'敏感操作':r.kind==='restart'?'需确认':'普通操作',r.sensitive?'red':'amber');}
function requestStatus(r){const map={pending:['等待审批','amber'],waiting:['等待确认保留','amber'],done:['执行完成','green'],kept:['已确认保留','green'],rolledback:['已恢复原配置','blue'],rejected:['已拒绝','red'],expired:['申请已过期',''],cancelled:['已取消','']};return badge(...(map[r.status]||['未知状态','']));}
function pending(){return state.requests.filter(r=>r.status==='pending');}
function activeOperationCount(){return state.clients.reduce((sum,c)=>sum+Object.values(c.operations).filter(t=>t>now()).length,0);}
function navTo(next){if(location.hash===`#${next}`){view=next;render();}else location.hash=next;}
function heading(title,description,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stopButton(){return btn(icon(state.paused?'play':'stop')+(state.paused?'恢复接受操作':'停止全部 AI 操作'),state.paused?'resume':'pause','','danger');}
function empty(title,description){return `<div class="empty">${icon('shield')}<strong>${title}</strong><p>${description}</p></div>`;}
function renderNav(){const items=[['overview','grid','运行概览'],['clients','users','客户端'],['permissions','shield','权限配置'],['approvals','clipboard','待审批'],['audit','clock','审计记录']];$('#nav').innerHTML=items.map(([id,i,title])=>`<a href="#${id}" class="nav-item ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${title}</span>${id==='approvals'&&pending().length?`<span class="count">${pending().length}</span>`:''}</a>`).join('');}
function renderAlerts(){let html='';if(state.paused)html+=`<div class="global-notice red">${icon('stop')}<div class="body"><strong>所有 AI 操作已停止</strong> · 查询仍然可用。临时操作授权已撤销，尚未执行的申请已取消。</div><button class="text-button" data-action="resume">恢复接受操作</button></div>`;for(const r of state.requests.filter(r=>r.status==='waiting'))html+=`<div class="global-notice">${icon('clock')}<div class="body"><strong>管理地址修改等待你确认保留</strong> · <span data-countdown="${r.deadline}">${clock(r.deadline-now())}</span> 后自动恢复原配置。停止 AI 操作不会取消恢复任务。</div><button class="text-button" data-action="review" data-id="${r.id}">查看并处理</button></div>`;$('#global-alert').innerHTML=html;}
function render(){enforceTime();renderNav();renderAlerts();const screens={overview:renderOverview,clients:renderClients,permissions:renderPermissions,approvals:renderApprovals,audit:renderAudit};$('#main').innerHTML=(screens[view]||renderOverview)();document.title=`${({overview:'运行概览',clients:'客户端',permissions:'权限配置',approvals:'待审批',audit:'审计记录'})[view]||'运行概览'} · MCP 权限管理`;}
function requestRow(r){const c=client(r.client);return `<div class="request-row"><div class="request-top"><span class="client-chip">${avatar(c)}${esc(c.name)}</span>${requestBadge(r)}</div><div class="request-title">${esc(r.title)}</div><p class="request-description">${esc(r.field)}<br><span class="mono">${esc(r.before)}</span> → <span class="mono">${esc(r.after)}</span></p><div class="request-bottom">${remaining(r)}${btn('审阅申请 '+icon('arrow'),'review',`data-id="${r.id}"`,'small')}</div></div>`;}
function renderOverview(){return heading('运行概览','看清当前授权，决定 AI 下一步可以做什么。',stopButton())+`<section class="status-strip" aria-label="服务状态"><div><div class="status-label">MCP 服务</div><div class="status-value"><span class="dot"></span>运行中 <small>模拟</small></div></div><div><div class="status-label">已接入客户端</div><div class="status-value">${state.clients.filter(c=>c.active).length} <small>个客户端</small></div></div><div><div class="status-label">临时操作授权</div><div class="status-value">${activeOperationCount()} <small>项生效中</small></div></div><div><div class="status-label">AI 操作总开关</div><div class="status-value">${badge(state.paused?'已停止':'接受授权申请',state.paused?'red':'green')}</div></div></section><div class="two-column"><div class="stack"><section class="panel"><header class="panel-header"><h2>${pending().length?'有 '+pending().length+' 项操作等待你的决定':'目前没有待处理申请'}</h2><span class="request-count">${pending().length?pending().length+' 项待审批':'已全部处理'}</span></header>${pending().slice(0,2).map(requestRow).join('')||empty('所有申请已处理','可以在演示控制台添加新的模拟申请。')}<div class="pending-summary">${icon('lock')}未获得授权的操作不会执行，查询不受影响。</div></section><section class="panel"><header class="panel-header"><h2>最近活动</h2><a href="#audit" class="text-button">查看全部</a></header>${state.audit.slice(0,4).map(a=>`<div class="activity"><span class="activity-dot ${a.tone==='amber'?'warning':a.tone==='red'?'danger':''}"></span><time>${timeLabel(a.time)}</time><div class="activity-text">${esc(clientName(a.client))} · ${esc(a.text)}</div>${badge(a.result,a.tone)}</div>`).join('')}</section></div><div class="stack overview-side"><section class="panel"><header class="panel-header"><h2>客户端授权</h2><a href="#clients" class="text-button">管理</a></header><div class="panel-body">${state.clients.slice(0,4).map(c=>`<div class="client-summary">${avatar(c)}<div class="body"><strong>${esc(c.name)}</strong><small>${c.active?c.queries.length+' 类查询 · '+Object.values(c.operations).filter(t=>t>now()).length+' 项临时操作':'令牌已撤销'}</small></div>${badge(c.active?'已接入':'已撤销',c.active?'green':'')}</div>`).join('')}</div></section><section class="panel"><header class="panel-header"><h2>当前保护规则</h2>${icon('shield')}</header><div class="panel-body policy-list">${[['key','默认不开放操作','普通操作授权 15 分钟后自动到期。'],['clipboard','敏感操作逐笔批准','绑定具体参数，仅执行一次。'],['refresh','未确认，自动恢复','敏感配置修改后有 120 秒确认时间。'],['link','仅通过内网或 VPN 管理','复用 LuCI 登录，AI 无管理权限。']].map(([i,t,d])=>`<div class="policy-line">${icon(i)}<div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div></section></div></div>`;}
function renderClients(){return heading('客户端','每个客户端独立授权。撤销令牌不会影响其他客户端。',btn(icon('plus')+'新增客户端','new-client','','primary'))+`<section class="panel"><header class="panel-header"><h2>已登记客户端 <small> / ${state.clients.length}</small></h2>${badge('令牌仅创建时显示一次','blue')}</header><div class="table-wrap"><table><thead><tr><th>客户端</th><th>连接状态</th><th>已开放查询</th><th>临时操作</th><th>调用上限</th><th>管理</th></tr></thead><tbody>${state.clients.map(c=>`<tr><td><div class="table-client">${avatar(c)}<div><strong>${esc(c.name)}</strong><small>${esc(c.description)}</small></div></div></td><td>${badge(c.active?'令牌有效':'已撤销',c.active?'green':'')}</td><td>${c.active?c.queries.length:0} 类查询</td><td>${c.active?Object.values(c.operations).filter(t=>t>now()).length:0} 项生效</td><td>${c.limit} 次 / 分钟</td><td><div class="actions-inline">${c.active?`<button class="text-button" data-action="client-permissions" data-id="${c.id}">配置权限</button><button class="text-button" data-action="limit" data-id="${c.id}">限流</button><button class="text-button danger" data-action="revoke" data-id="${c.id}">撤销令牌</button>`:'<span class="neutral-label">需新建客户端重新接入</span>'}</div></td></tr>`).join('')}</tbody></table></div><div class="audit-footer">撤销后立即拒绝该客户端的 MCP 请求，并取消它尚未执行的申请。已经开始的配置恢复任务会继续。</div></section><div class="note section-gap">${icon('info')}<div>这里管理的是 MCP 客户端，不是路由器上的联网设备。原型中的连接状态和令牌均为模拟。</div></div>`;}
function renderPermissions(){let c=client(selectedClient);if(!c){c=state.clients[0];selectedClient=c.id;}return heading('权限配置','选择客户端，分别管理查询、临时操作和敏感操作。')+`<div class="permissions-layout"><aside class="panel client-selector" aria-label="选择客户端"><div class="client-selector-label">客户端</div>${state.clients.map(item=>`<button class="client-select ${c.id===item.id?'active':''}" data-action="select-client" data-id="${item.id}">${avatar(item)}<span class="body">${esc(item.name)}<small>${item.active?'独立权限策略':'令牌已撤销'}</small></span></button>`).join('')}</aside><div class="stack"><section class="panel"><header class="panel-header"><h2>${esc(c.name)} 的权限</h2>${badge(c.active?'令牌有效':'已撤销',c.active?'green':'')}</header><div class="permission-section"><h3>查询权限</h3><p>可长期开放。开关即时生效，并记录到审计日志。</p>${queryGroups.map(([key,title,desc,i])=>`<div class="permission-row"><span class="permission-icon">${icon(i)}</span><div class="body"><strong>${title}</strong><small>${desc}</small></div><div class="permission-controls"><span class="neutral-label">${c.queries.includes(key)?'长期开放':'未开放'}</span><button class="switch" role="switch" aria-label="${esc(c.name)}：${title}" aria-checked="${c.active&&c.queries.includes(key)}" data-action="toggle-query" data-key="${key}" ${!c.active?'disabled':''}></button></div></div>`).join('')}</div><div class="divider"></div><div class="permission-section"><h3>临时操作权限</h3><p>默认关闭，仅在明确授权的时间内有效。停止总开关会收回全部临时授权。</p>${operationGroups.map(([key,title,desc,i])=>{const active=c.operations[key]>now();return `<div class="permission-row"><span class="permission-icon">${icon(i)}</span><div class="body"><strong>${title}</strong><small>${desc}${active?` · <span data-grant="${c.operations[key]}">${clock(c.operations[key]-now())}</span> 后收回`:''}</small></div><div class="permission-controls">${key==='restart'?badge('逐笔审批','amber'):badge(active?'临时开放':'默认关闭',active?'green':'')}${key==='restart'?'<span class="neutral-label">按申请批准</span>':btn(active?'收回授权':'临时开放',active?'revoke-grant':'grant',`data-key="${key}" ${!c.active||state.paused?'disabled':''}`,'small')}</div></div>`;}).join('')}</div><div class="divider"></div><div class="permission-section"><h3>敏感操作</h3><p>不提供长期或批量开放。只有你批准的具体修改可以执行一次。</p><div class="permission-row"><span class="permission-icon">${icon('lock')}</span><div class="body"><strong>管理地址、端口及管理访问规则</strong><small>5 分钟内逐笔审批；可回滚的修改需在 120 秒内确认保留。</small></div><div class="permission-controls">${badge('逐笔审批','red')}</div></div></div><div class="scope-note">AI 可以提交申请，但不能修改自身权限或批准操作。客户端撤销、总开关、有效期与具体参数校验，在生产实现中均由服务端强制执行。</div></section></div></div>`;}
function renderApprovals(){const requests=[...state.requests].reverse();let r=state.requests.find(item=>item.id===selectedRequest);if(!r)r=requests[0];return heading('待审批','你批准的是一笔具体操作，而不是一项无限制能力。',btn(icon('plus')+'添加模拟申请','add-request'))+`<div class="approvals-layout"><aside class="panel request-list" aria-label="审批申请列表">${requests.map(item=>`<button class="request-select ${r?.id===item.id?'active':''}" data-action="select-request" data-id="${item.id}"><div class="request-top"><span class="client-chip">${avatar(client(item.client))}${esc(clientName(item.client))}</span>${requestBadge(item)}</div><div class="request-title">${esc(item.title)}</div><div class="request-bottom">${requestStatus(item)}${item.status==='pending'?remaining(item):`<span class="remaining">${esc(item.id)}</span>`}</div></button>`).join('')||empty('还没有申请','可添加模拟申请体验审批。')}</aside><section class="panel" id="request-detail">${r?renderRequestDetail(r):empty('选择一笔申请','在这里查看变更内容与恢复方式。')}</section></div>`;}
function renderRequestDetail(r){const c=client(r.client),isPending=r.status==='pending';if(r.status==='waiting')return `<div class="panel-body"><div class="detail-id mono">${esc(r.id)} · ${esc(c.name)} · 模拟执行</div><div class="detail-heading"><h2>修改已执行，等待你的确认</h2>${requestBadge(r)}</div><p class="request-description">管理地址 <span class="mono">${esc(r.before)} → ${esc(r.after)}</span></p>${renderRecovery(r)}</div>`;const granted=!r.requiresReview&&c.operations[r.kind]>now();return `<div class="panel-body"><div class="detail-id mono">${esc(r.id)} · 模拟申请</div><div class="detail-heading"><h2>${esc(r.title)}</h2>${requestBadge(r)}</div><p class="request-description">${esc(r.reason)}</p><dl class="detail-meta"><div><dt>申请客户端</dt><dd>${esc(c.name)}</dd></div><div><dt>执行方式</dt><dd>${r.requiresReview?'逐笔批准，仅执行一次':granted?'使用现有临时授权':'临时授权后执行'}</dd></div><div><dt>申请状态</dt><dd>${requestStatus(r)}</dd></div></dl><div class="detail-section"><h3>具体变更</h3><p class="mono">${esc(r.field)}</p><div class="diff"><div class="diff-box"><small>变更前</small><strong class="mono">${esc(r.before)}</strong></div><div class="diff-arrow">${icon('arrow')}</div><div class="diff-box new"><small>变更后</small><strong class="mono">${esc(r.after)}</strong></div></div></div>${r.sensitive?`<div class="note amber">${icon('info')}<div><strong>管理连接可能中断</strong><br>执行后需要通过新地址重新进入管理页，由你确认保留；120 秒内未确认则恢复原地址。本原型只模拟这一过程。</div></div>`:`<div class="note">${icon('info')}<div>${r.kind==='restart'?'重启时代理连接可能短暂中断。这是一次性服务动作，不提供配置回滚承诺。':granted?'当前已有有效临时授权，可直接模拟执行，不延长原授权的到期时间。':'只切换现有代理组中的节点，不修改订阅或代理规则。普通操作授权默认 15 分钟。'}</div></div>`}<div class="detail-section"><h3>授权边界</h3><ul><li>申请在创建后 5 分钟过期，批准前再次校验。</li><li>绑定当前客户端及以上参数，变更内容需重新申请。</li><li>${r.sensitive?'恢复任务独立运行，AI 无权确认保留。':'执行结果记录到该客户端的审计日志。'}</li></ul></div>${isPending?`<div class="detail-footer">${btn(r.requiresReview?'批准并执行一次':granted?'按现有授权模拟执行':'授权 15 分钟并执行',granted?'execute-granted':'approve',`data-id="${r.id}" ${state.paused||!c.active?'disabled':''}`,'primary')}${btn('拒绝申请','reject',`data-id="${r.id}"`)}${remaining(r)}</div>`:renderResult(r)}</div>`;}
function renderRecovery(r){return `<div class="timeline"><div class="timeline-step"><span class="step-mark">${icon('check')}</span><div>你已逐笔批准<small>参数已锁定，不能复用本次批准。</small></div></div><div class="timeline-step"><span class="step-mark">${icon('check')}</span><div>修改已执行，恢复快照已保存<small>新管理地址：<span class="mono">${esc(r.after)}</span>（模拟）</small></div></div><div class="timeline-step ${r.reconnected?'':'muted'}"><span class="step-mark">${icon(r.reconnected?'check':'link')}</span><div>${r.reconnected?'已模拟通过新地址重新连接':'等待通过新地址重新连接'}</div></div></div><div class="countdown"><div class="countdown-header"><h3>确认保留这次修改</h3><strong data-countdown="${r.deadline}">${clock(r.deadline-now())}</strong></div><p>超过倒计时将恢复为 <span class="mono">${esc(r.before)}</span>，只有管理员可以确认保留。</p><div class="progress"><span data-progress="${r.deadline}" style="width:${Math.max(0,(r.deadline-now())/1200)}%"></span></div></div><div class="detail-footer">${!r.reconnected?btn('模拟通过新地址重新连接','reconnect',`data-id="${r.id}"`,'primary'):btn('确认保留修改','keep',`data-id="${r.id}"`,'primary')}${btn('立即恢复原配置','rollback',`data-id="${r.id}"`)}<small>这不会访问真实地址</small></div>`;}
function renderResult(r){const info={done:['操作已完成','本申请已经执行一次，不能再次批准。'],kept:['修改已保留','你已确认新地址可用，自动恢复任务已取消。'],rolledback:['原配置已恢复','管理地址已恢复为 '+r.before+'（模拟）。'],rejected:['申请已拒绝','没有执行任何变更。客户端可以重新提交新的申请。'],expired:['申请已过期','没有执行任何变更。需要客户端重新提交申请。'],cancelled:['申请已取消','总开关停止、客户端撤销或模拟重启使本申请失效。']};const [title,desc]=info[r.status]||['申请已结束',''];return `<div class="note ${r.status==='rejected'?'red':''}">${icon(r.status==='done'||r.status==='kept'?'check':'info')}<div><strong>${title}</strong><br>${esc(desc)}</div></div>`;}
function renderAudit(){const rows=state.audit.filter(a=>(filterClient==='all'||a.client===filterClient)&&(filterResult==='all'||a.type===filterResult)&&(!search||(clientName(a.client)+' '+a.text+' '+a.result).toLowerCase().includes(search.toLowerCase())));return heading('审计记录','授权、审批、执行和恢复均有迹可查。敏感内容自动隐藏。',btn('导出当前记录','export'))+`<div class="toolbar"><select class="filter" id="audit-client" aria-label="筛选客户端"><option value="all">全部客户端</option><option value="admin" ${filterClient==='admin'?'selected':''}>管理员</option>${state.clients.map(c=>`<option value="${c.id}" ${filterClient===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select class="filter" id="audit-type" aria-label="筛选记录类型">${[['all','全部事件'],['request','申请与审批'],['grant','授权变更'],['operation','执行与恢复'],['query','状态查询']].map(([v,t])=>`<option value="${v}" ${filterResult===v?'selected':''}>${t}</option>`).join('')}</select><div class="audit-search-wrap"><input class="search" id="audit-search" placeholder="搜索操作、客户端或结果" value="${esc(search)}" aria-label="搜索审计记录"></div><span class="neutral-label">${rows.length} 条记录</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>时间</th><th>客户端 / 操作人</th><th>事件</th><th>结果</th></tr></thead><tbody>${rows.map(a=>`<tr><td class="mono">${timeLabel(a.time)}<small>今天 · 模拟</small></td><td>${esc(clientName(a.client))}</td><td class="audit-event">${esc(a.text)}</td><td>${badge(a.result,a.tone)}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('没有匹配的记录','调整筛选条件或清空搜索后再试。')}<div class="audit-footer">保留策略：7 天或 16 MB，先达到哪个就清理哪个。令牌、密码、订阅地址均不写入日志。未完成的恢复快照独立保留。<br>原型仅在当前页面内存中保存模拟记录，刷新或重置后恢复初始状态。</div></section>`;}
function openDialog(title,body,footer){dialogReturnFocus=document.activeElement;const d=$('#dialog');if(d.open)d.close();d.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="关闭对话框">${icon('close')}</button></div><div class="dialog-body">${body}</div><div class="dialog-footer">${footer}</div>`;d.showModal();}
function closeDialog(){const d=$('#dialog');d.close();if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus();}
function requestEligible(r){if(!r||r.status!=='pending')return'申请已结束，不能重复执行';if(r.expires<=now())return'申请已过期，请重新提交';if(state.paused)return'总开关已停止，无法执行操作';if(!client(r.client)?.active)return'客户端令牌已撤销';return'';}
function ensureEligible(r){const error=requestEligible(r);if(error){closeDialog();enforceTime();render();toast(error);return false;}return true;}
function execute(r,existingGrant=false){if(!ensureEligible(r))return;const c=client(r.client);if(existingGrant&&(r.requiresReview||!(c.operations[r.kind]>now()))){render();toast('临时授权已失效，请重新申请');return;}if(r.sensitive){r.status='waiting';r.deadline=now()+120000;addAudit(r.client,`逐笔批准管理地址 ${r.before} → ${r.after}，等待人工确认`,'等待确认保留','amber');}else{r.status='done';if(r.kind!=='restart'&&!existingGrant){c.operations[r.kind]=now()+900000;addAudit('admin',`为 ${c.name} 临时开放节点切换 15 分钟`,'临时授权生效','blue','grant');}addAudit(r.client,r.kind==='restart'?'执行 OpenClash 服务重启':`切换 PROXY 节点：${r.before} → ${r.after}`,'执行完成','green');}closeDialog();selectedRequest=r.id;render();toast(r.sensitive?'模拟修改已执行，120 秒内确认保留':'模拟操作已执行');}
function finishRecovery(r,status,reason){if(!r||r.status!=='waiting')return;r.status=status;addAudit('admin',reason,status==='kept'?'已确认保留':'已恢复原配置',status==='kept'?'green':'blue');}
function enforceTime(){if(!state)return false;let changed=false;for(const r of state.requests){if(r.status==='pending'&&r.expires<=now()){r.status='expired';addAudit(r.client,r.title+'：申请有效期已结束','已过期','','request');changed=true;}if(r.status==='waiting'&&r.deadline<=now()){finishRecovery(r,'rolledback','确认超时，自动恢复管理地址为 '+r.before);changed=true;}}for(const c of state.clients)for(const [key,deadline]of Object.entries(c.operations)){if(deadline<=now()){delete c.operations[key];addAudit('admin',c.name+' 的临时操作授权到期收回','授权已到期','','grant');changed=true;}}return changed;}
function addRequest(kind='node'){if(state.paused){toast('请先恢复接受操作，再添加模拟申请');return;}const c=state.clients.find(c=>c.active);if(!c){toast('请先新增客户端');return;}const id='REQ-'+String(243+state.requests.length-2).padStart(4,'0');const r=makeRequest(id,c.id,kind);state.requests.push(r);selectedRequest=r.id;addAudit(c.id,'申请'+r.title,'等待审批','amber','request');closeDialog();navTo('approvals');render();toast('已添加一笔模拟申请');}
function showDemo(){openDialog('演示控制台',`<p>用模拟事件体验不同状态，不会向真实路由器发送请求。</p><div class="demo-actions section-gap">${btn(icon('network')+'<span>添加节点切换申请<small>体验 15 分钟临时授权</small></span>','demo-node')}${btn(icon('lock')+'<span>添加管理地址修改申请<small>体验逐笔批准与 120 秒恢复</small></span>','demo-lan')}${btn(icon('clock')+'<span>快进 5 分钟<small>使等待中的申请过期，触发到期恢复</small></span>','fast-forward')}${btn(icon('refresh')+'<span>模拟路由器重启<small>清除临时授权，恢复未确认修改</small></span>','restart-simulation')}${btn(icon('grid')+'<span>重置全部演示<small>恢复初始客户端和两笔申请</small></span>','reset')}</div>`,btn('关闭','close'));}
function reset(){offset=0;state=freshState();selectedClient='codex';selectedRequest='REQ-0241';filterClient='all';filterResult='all';search='';if($('#dialog').open)closeDialog();navTo('overview');render();toast('已恢复初始模拟数据');}
const actions={
  close:()=>closeDialog(),demo:showDemo,reset,
  review:b=>{selectedRequest=b.dataset.id;navTo('approvals');render();},
  'select-request':b=>{selectedRequest=b.dataset.id;render();},
  'select-client':b=>{selectedClient=b.dataset.id;render();},
  'client-permissions':b=>{selectedClient=b.dataset.id;navTo('permissions');},
  'toggle-query':b=>{const c=client(selectedClient);if(!c.active)return;const key=b.dataset.key,enabled=c.queries.includes(key);c.queries=enabled?c.queries.filter(k=>k!==key):[...c.queries,key];addAudit('admin',`${enabled?'关闭':'开启'} ${c.name} 的${queryGroups.find(g=>g[0]===key)[1]}查询`,'授权已更新','blue','grant');render();document.querySelector(`[data-action="toggle-query"][data-key="${key}"]`)?.focus({preventScroll:true});toast('查询权限已'+(enabled?'关闭':'开启')+'（模拟）');},
  grant:b=>{const c=client(selectedClient);if(!c.active||state.paused)return;const key=b.dataset.key;openDialog('临时开放操作',`<p>为 <strong>${esc(c.name)}</strong> 开放“${operationGroups.find(g=>g[0]===key)[1]}”。有效期内，该客户端可直接执行此项普通操作。</p><div class="field"><label for="grant-duration">授权有效期</label><select id="grant-duration"><option value="15">15 分钟（默认）</option><option value="30">30 分钟</option><option value="60">60 分钟</option></select></div><div class="note">${icon('clock')}到期自动收回，不会变成长期权限。</div>`,btn('取消','close')+btn('确认临时开放','confirm-grant',`data-key="${key}" data-client="${c.id}"`,'primary'));},
  'confirm-grant':b=>{const c=client(b.dataset.client);if(!c?.active||state.paused){closeDialog();toast('客户端已撤销或操作已停止');return;}const minutes=Number($('#grant-duration').value);c.operations[b.dataset.key]=now()+minutes*60000;addAudit('admin',`为 ${c.name} 临时开放${operationGroups.find(g=>g[0]===b.dataset.key)[1]} ${minutes} 分钟`,'临时授权生效','blue','grant');closeDialog();render();toast('临时授权已生效（模拟）');},
  'revoke-grant':b=>{const c=client(selectedClient);delete c.operations[b.dataset.key];addAudit('admin','收回 '+c.name+' 的临时操作权限','授权已收回','','grant');render();toast('已收回该项临时授权');},
  approve:b=>{const r=state.requests.find(r=>r.id===b.dataset.id);if(!ensureEligible(r))return;openDialog(r.sensitive?'批准这笔敏感修改？':r.kind==='restart'?'批准服务重启？':'授权并执行节点切换？',`<p>申请来自 <strong>${esc(clientName(r.client))}</strong>，只执行下列具体内容。</p><div class="diff"><div class="diff-box"><small>变更前</small><strong>${esc(r.before)}</strong></div><div class="diff-arrow">${icon('arrow')}</div><div class="diff-box new"><small>变更后</small><strong>${esc(r.after)}</strong></div></div>${r.sensitive?`<div class="note amber">${icon('info')}执行后管理连接可能中断，120 秒内需由你重新连接并确认保留，超时恢复原配置。</div><label class="check-label"><input type="checkbox" id="risk-check">我已核对具体变更，了解连接可能中断及恢复方式。</label>`:`<p>${r.kind==='restart'?'这次批准只执行一次服务重启，不会开放长期重启权限。':'同时开放该客户端 15 分钟节点切换权限，到期自动收回。'}</p>`}`,btn('返回核对','close')+btn(r.sensitive?'批准并执行一次':'确认执行','execute',`data-id="${r.id}" ${r.sensitive?'disabled':''}`,r.sensitive?'danger-solid':'primary'));},
  execute:b=>execute(state.requests.find(r=>r.id===b.dataset.id)),
  'execute-granted':b=>execute(state.requests.find(r=>r.id===b.dataset.id),true),
  reject:b=>{const r=state.requests.find(r=>r.id===b.dataset.id);if(!r||r.status!=='pending')return;r.status='rejected';addAudit('admin','拒绝 '+clientName(r.client)+' 的'+r.title,'已拒绝','red','request');render();toast('已拒绝申请，没有执行变更');},
  reconnect:b=>{const r=state.requests.find(r=>r.id===b.dataset.id);if(r?.status!=='waiting')return;r.reconnected=true;render();toast('已模拟通过新管理地址重新连接');},
  keep:b=>{const r=state.requests.find(r=>r.id===b.dataset.id);enforceTime();if(r?.status!=='waiting'||!r.reconnected){render();toast('确认窗口已结束或尚未重新连接');return;}openDialog('确认保留新的管理地址？',`<p>你已模拟通过 <strong class="mono">${esc(r.after)}</strong> 重新连接。确认后将保留这笔修改，并取消本次自动恢复任务。</p>`,btn('继续核对','close')+btn('确认保留','confirm-keep',`data-id="${r.id}"`,'primary'));},
  'confirm-keep':b=>{const r=state.requests.find(r=>r.id===b.dataset.id);enforceTime();if(r?.status==='waiting'&&r.reconnected){finishRecovery(r,'kept','管理员确认新管理地址 '+r.after+' 可用并保留修改');toast('修改已保留，自动恢复任务已取消');}else toast('确认窗口已结束，原配置已恢复');closeDialog();render();},
  rollback:b=>{const r=state.requests.find(r=>r.id===b.dataset.id);finishRecovery(r,'rolledback','管理员立即恢复管理地址为 '+r.before);render();toast('已恢复原配置（模拟）');},
  pause:()=>openDialog('停止全部 AI 操作？',`<p>立即收回所有客户端的临时操作授权，取消尚未执行的申请。<strong>查询能力会保留。</strong></p><div class="note amber section-gap">${icon('info')}已经执行的修改不会因此自动撤销；未确认修改的恢复倒计时将继续。此开关不限制 root SSH。</div>`,btn('取消','close')+btn('停止全部操作','confirm-pause','','danger-solid')),
  'confirm-pause':()=>{state.paused=true;for(const c of state.clients)c.operations={};for(const r of state.requests)if(r.status==='pending')r.status='cancelled';addAudit('admin','停止全部 AI 操作，撤销临时授权并取消待执行申请','操作已停止','red','grant');closeDialog();render();toast('操作已停止，查询和恢复任务继续');},
  resume:()=>{state.paused=false;addAudit('admin','恢复接受操作申请，未恢复旧授权','接受新申请','blue','grant');render();toast('已恢复接受申请，旧授权和旧申请不会恢复');},
  'new-client':()=>openDialog('新增 MCP 客户端',`<p>创建独立令牌，随后为客户端配置权限。默认不开放任何查询或操作。</p><div class="field"><label for="client-name">客户端名称</label><input id="client-name" maxlength="32" placeholder="例如：家庭助手" autocomplete="off"></div><div class="field"><label for="client-description">用途说明（选填）</label><input id="client-description" maxlength="60" placeholder="方便以后识别这个客户端"></div><div class="field-error" id="client-error" role="alert"></div>`,btn('取消','close')+btn('创建并生成演示令牌','create-client','','primary')),
  'create-client':()=>{const name=$('#client-name').value.trim();if(!name){$('#client-error').textContent='请输入客户端名称。';$('#client-name').focus();return;}if(state.clients.some(c=>c.name.toLowerCase()===name.toLowerCase())){$('#client-error').textContent='名称已存在，请使用其他名称。';return;}const c={id:'client-'+Date.now(),name,description:$('#client-description').value.trim()||'自定义客户端',active:true,queries:[],operations:{},limit:60};state.clients.push(c);addAudit('admin','创建客户端 '+name,'客户端已创建','blue','grant');selectedClient=c.id;view='clients';location.hash='#clients';openDialog('客户端已创建',`<p><strong>${esc(name)}</strong> 的演示令牌仅在此处显示一次。原型令牌无效，不能连接真实服务。</p><div class="token mono">demo_only_${esc(c.id)}_not_a_real_token</div><div class="note">${icon('key')}生产环境只保存令牌摘要；关闭窗口后不能再次查看原令牌。</div>`,btn('已了解，配置权限','new-client-permissions'));render();},
  'new-client-permissions':()=>{closeDialog();navTo('permissions');},
  revoke:b=>{const c=client(b.dataset.id);openDialog('撤销 '+esc(c.name)+' 的令牌？',`<p>撤销后，该客户端将无法通过 MCP 查询或执行操作，尚未执行的申请也会取消。其他客户端不受影响。</p><div class="note amber section-gap">${icon('info')}这个动作无法撤销。若需重新接入，请创建新客户端和令牌。</div>`,btn('取消','close')+btn('撤销令牌','confirm-revoke',`data-id="${c.id}"`,'danger-solid'));},
  'confirm-revoke':b=>{const c=client(b.dataset.id);c.active=false;c.operations={};for(const r of state.requests)if(r.client===c.id&&r.status==='pending')r.status='cancelled';addAudit('admin','撤销 '+c.name+' 的令牌并取消未执行申请','令牌已撤销','red','grant');closeDialog();render();toast('已撤销该客户端令牌');},
  limit:b=>{const c=client(b.dataset.id);openDialog('设置调用频率',`<p>限制 ${esc(c.name)} 的 MCP 调用频率。</p><div class="field"><label for="rate-limit">每分钟最大调用次数</label><input type="number" id="rate-limit" min="1" max="600" value="${c.limit}"></div><div class="field-error" id="limit-error" role="alert"></div>`,btn('取消','close')+btn('保存上限','save-limit',`data-id="${c.id}"`,'primary'));},
  'save-limit':b=>{const n=Number($('#rate-limit').value);if(!Number.isInteger(n)||n<1||n>600){$('#limit-error').textContent='请输入 1 到 600 的整数。';return;}const c=client(b.dataset.id);c.limit=n;addAudit('admin','将 '+c.name+' 的调用上限设为 '+n+' 次/分钟','限流已更新','blue','grant');closeDialog();render();toast('调用上限已保存（模拟）');},
  'add-request':()=>openDialog('添加模拟申请',`<p>选择一种操作，体验它的申请与审批过程。</p><div class="demo-actions section-gap">${btn('切换 OpenClash 节点','demo-node')}${btn('修改 LAN 管理地址','demo-lan')}${btn('重启 OpenClash 服务','demo-restart')}</div>`,btn('取消','close')),
  'demo-node':()=>addRequest('node'),'demo-lan':()=>addRequest('lan'),'demo-restart':()=>addRequest('restart'),
  'fast-forward':()=>{offset+=300000;closeDialog();render();toast('模拟时间已快进 5 分钟');},
  'restart-simulation':()=>{for(const c of state.clients)c.operations={};for(const r of state.requests){if(r.status==='pending')r.status='cancelled';if(r.status==='waiting')finishRecovery(r,'rolledback','模拟重启：启动时恢复未确认的管理地址修改');}addAudit('admin','模拟路由器重启：清除临时授权和待执行审批，保留查询','重启恢复完成','blue');closeDialog();render();toast('模拟重启完成，查询授权保留');},
  export:()=>{const rows=state.audit.filter(a=>(filterClient==='all'||a.client===filterClient)&&(filterResult==='all'||a.type===filterResult)&&(!search||(clientName(a.client)+' '+a.text+' '+a.result).toLowerCase().includes(search.toLowerCase())));const data=JSON.stringify({simulation:true,retention:'7天或16MB',records:rows},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='mcp-audit-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出筛选后的模拟审计记录');}
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;actions[b.dataset.action]?.(b);});
document.addEventListener('change',e=>{if(e.target.id==='risk-check'){const b=$('[data-action="execute"]');if(b)b.disabled=!e.target.checked;}if(e.target.id==='audit-client'){filterClient=e.target.value;render();}if(e.target.id==='audit-type'){filterResult=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='audit-search'){const position=e.target.selectionStart;search=e.target.value;render();const input=$('#audit-search');input.focus();input.setSelectionRange(position,position);}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'overview';if(!['overview','clients','permissions','approvals','audit'].includes(view))view='overview';render();window.scrollTo({top:0,behavior:'instant'});});
setInterval(()=>{if(enforceTime()){render();return;}for(const el of document.querySelectorAll('[data-expires]'))el.textContent=clock(Number(el.dataset.expires)-now())+' 后失效';for(const el of document.querySelectorAll('[data-countdown]'))el.textContent=clock(Number(el.dataset.countdown)-now());for(const el of document.querySelectorAll('[data-grant]'))el.textContent=clock(Number(el.dataset.grant)-now());for(const el of document.querySelectorAll('[data-progress]'))el.style.width=Math.max(0,(Number(el.dataset.progress)-now())/1200)+'%';},1000);
state=freshState();view=location.hash.slice(1)||'overview';render();

